ALTER TABLE pos_sales ADD COLUMN discount_cents BIGINT NOT NULL DEFAULT 0 CHECK(discount_cents>=0), ADD COLUMN tax_cents BIGINT NOT NULL DEFAULT 0 CHECK(tax_cents>=0), ADD COLUMN subtotal_cents BIGINT NOT NULL DEFAULT 0 CHECK(subtotal_cents>=0);
ALTER TABLE commercial_documents ADD COLUMN approved_by UUID REFERENCES users(id) ON DELETE SET NULL, ADD COLUMN approved_at TIMESTAMPTZ, ADD COLUMN approval_note TEXT NOT NULL DEFAULT '' CHECK(length(approval_note)<=1000);
CREATE TABLE report_schedules (id UUID PRIMARY KEY,company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,report_key TEXT NOT NULL CHECK(report_key IN ('attendance','payroll','leave','accounting')),format TEXT NOT NULL CHECK(format IN ('csv','pdf')),frequency TEXT NOT NULL CHECK(frequency IN ('daily','weekly','monthly')),recipient_email TEXT NOT NULL CHECK(length(recipient_email)<=320),is_active BOOLEAN NOT NULL DEFAULT true,last_run_at TIMESTAMPTZ,next_run_at TIMESTAMPTZ,created_by UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX report_schedules_due_idx ON report_schedules(company_id,is_active,next_run_at);
ALTER TABLE device_sync_devices ADD COLUMN credential_hash TEXT, ADD COLUMN credential_expires_at TIMESTAMPTZ, ADD COLUMN conflict_count INTEGER NOT NULL DEFAULT 0;
CREATE TABLE device_sync_media_queue (id UUID PRIMARY KEY,company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,device_id UUID NOT NULL REFERENCES device_sync_devices(id) ON DELETE CASCADE,file_id UUID REFERENCES private_files(id) ON DELETE SET NULL,idempotency_key TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','uploaded','failed')),metadata JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(device_id,idempotency_key));
CREATE TABLE attendance_integrity_policies (company_id UUID PRIMARY KEY REFERENCES companies(id) ON DELETE CASCADE,min_accuracy_meters INTEGER NOT NULL DEFAULT 100,max_speed_kmh INTEGER NOT NULL DEFAULT 180,retention_days INTEGER NOT NULL DEFAULT 180,reviewer_user_id UUID REFERENCES users(id) ON DELETE SET NULL,require_device_attestation BOOLEAN NOT NULL DEFAULT false,updated_by UUID REFERENCES users(id) ON DELETE SET NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
